import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the test contract so we can deal Ether to an actor
        vm.deal(address(this), 1 ether);
        // Call go with 0.5 ether
        vm.deal(address(0x123), 0.5 ether);
        vm.prank(address(0x123));
