        vm.deal(address(this), 1 ether);
        (bool ok, ) = address(c).call{value: 1 ether}("");
        assertTrue(ok);
        // Now call go() with 1 ether. Reference forwards 1 ether, buggy forwards 0.
        vm.deal(address(this), 1 ether);
        c.go{value: 1 ether}();
        // After go(), reference forwards all 2 ether to target -> target is 0xC8A60... (not this contract),
        // then sends remaining balance (0) to owner.
        // Buggy forwards 0 to target, so 1 ether (from initial plus 1 msg.value) minus 0 sent = 1 ether still in c?
        // Actually target call with value 0 doesn't spend, so c.balance after go() includes the initial 1 ether?
        // But owner.transfer drains all balance: msg.value=1 ether + initial 1 ether = 2 ether.
        // Buggy: target call with 0 -> no ETH sent; owner gets 2 ether -> c.balance = 0.
        // Reference: target call with 1 ether -> sends 1 ether to target; owner gets 1 ether -> c.balance = 0.
        // Actually both end with c.balance=0. So we need another divergence.
        // Instead, let's first send 2 ether to c via fallback, then call go with 1 ether.
        // Reference: target gets 1 ether, owner gets (2+1-1)=2 ether, c.balance=0.
        // Buggy: target gets 0, owner gets (2+1)=3, c.balance=0.
        // Still both end same.
        // Need the target to be this contract? Target is fixed 0xC8A..., not us.
        // The only observable difference is the return of target.call? But we don't track that.
        // Actually target.call returns a bool; if target reverts, reference reverts too.
        // Since target is random address, it likely has no payable fallback -> call with value reverts for reference but not for buggy (value 0).
        vm.deal(address(this), 1 ether);
        bool refOk;
        try c.go{value: 1 ether}() { refOk = true; } catch { refOk = false; }
        // Reference sends 1 ether to 0xC8A..., which likely fails -> revert -> refOk=false.
        // Buggy sends 0 to 0xC8A..., succeeds -> refOk=true.
        assertTrue(!refOk); // reference fails, buggy succeeds -> assertion fails on buggy because refOk is true there
    }
}

